type ProgressivePauseLifecycleStage string

const (
	// Pauses during service reconciliation when more than one service revision is active.
	ProgressivePauseLifecycleStage_RECONCILE_SERVICE = ProgressivePauseLifecycleStage("RECONCILE_SERVICE")
	// Pauses before ECS starts tasks for the new service revision.
	ProgressivePauseLifecycleStage_PRE_SCALE_UP = ProgressivePauseLifecycleStage("PRE_SCALE_UP")
	// Pauses after tasks for the new service revision have started and become healthy, before they
	// receive traffic.
	ProgressivePauseLifecycleStage_POST_SCALE_UP = ProgressivePauseLifecycleStage("POST_SCALE_UP")
	// Pauses after the test traffic shift completes and before production traffic shifts. Use with a
	// test route to inspect or validate the new revision.
	ProgressivePauseLifecycleStage_POST_TEST_TRAFFIC_SHIFT = ProgressivePauseLifecycleStage("POST_TEST_TRAFFIC_SHIFT")
	// Pauses before production traffic shifts to the new service revision. Canary and linear
	// deployments pause before each traffic shift step, with a new hookId to continue each time.
	ProgressivePauseLifecycleStage_PRE_PRODUCTION_TRAFFIC_SHIFT = ProgressivePauseLifecycleStage("PRE_PRODUCTION_TRAFFIC_SHIFT")
	// Pauses after all production traffic has shifted to the new service revision.
	ProgressivePauseLifecycleStage_POST_PRODUCTION_TRAFFIC_SHIFT = ProgressivePauseLifecycleStage("POST_PRODUCTION_TRAFFIC_SHIFT")
)

